import{H as e,Q as t,ht as n,nt as r,tt as i}from"./chunks/framework.DiAOIirN.js";import"./chunks/assets.CN5ja4nF.js";var a=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"imap-mcp","text":"Your mailbox as tools, without a way to send","tagline":"Find the mail, read it, file it — every message fenced as untrusted content, and the write tools off unless you turn them on","actions":[{"theme":"brand","text":"Get started","link":"/guide/getting-started"},{"theme":"alt","text":"Tools reference","link":"/reference/tools"},{"theme":"alt","text":"GitHub","link":"https://github.com/ni-c/imap-mcp"}]},"features":[{"title":"Mail is evidence, not instruction","details":"Anyone in the world can send you mail, so every body arrives fenced between BEGIN/END UNTRUSTED EMAIL CONTENT markers carrying a random nonce, with that nonce repeated on every line inside. Text outside those markers is the only text this server wrote."},{"title":"It knows what is new","details":"list_new_messages tracks what the assistant has already seen with its own IMAP keyword, so \\"anything new?\\" has an answer that does not depend on whether you have read the mail yourself — and reading it here does not mark it read in your client."},{"title":"Only the tools you want","details":"IMAP_READ_ONLY=true registers the read tools and nothing else. IMAP_ALLOW_TOOLS cuts finer — essential for a curated handful, your own comma-separated list, or a whole family with list_* — and IMAP_DENY_TOOLS subtracts. Whatever is filtered out does not exist on the protocol rather than failing when called, and a name that matches no tool stops the server at startup instead of quietly going missing."},{"title":"Safe by default","details":"Deleting messages, moving or copying them and deleting a folder ask a person first, through MCP elicitation — a dialog the model cannot answer on its behalf, falling back to a server-issued token where the client cannot show one. Upstream content is marked untrusted, and read-only mode simply does not register the write tools."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1788380633000}`),o={name:`index.md`};function s(e,a,o,s,c,l){return n(),i(`div`,null,[...a[0]||=[t(`figure`,{class:`diagram`},[t(`svg`,{viewBox:`0 0 720 268`,role:`img`,"aria-labelledby":`arch-title arch-desc`},[t(`title`,{id:`arch-title`},`How imap-mcp sits between an MCP client and a mailbox`),t(`desc`,{id:`arch-desc`},`An MCP client speaks stdio to imap-mcp, which connects to an IMAP server over TLS; message bodies come back fenced as untrusted content.`),t(`defs`,null,[t(`marker`,{id:`arch-arrow`,markerWidth:`9`,markerHeight:`9`,refX:`7`,refY:`3`,orient:`auto`},[t(`path`,{d:`M0,0 L7,3 L0,6 z`})]),t(`marker`,{id:`arch-arrow-accent`,class:`accent`,markerWidth:`9`,markerHeight:`9`,refX:`7`,refY:`3`,orient:`auto`},[t(`path`,{d:`M0,0 L7,3 L0,6 z`})])]),t(`rect`,{class:`node`,x:`20`,y:`70`,width:`160`,height:`80`,rx:`10`}),t(`text`,{class:`label-title`,x:`100`,y:`103`,"text-anchor":`middle`},`MCP client`),t(`text`,{class:`label-muted`,x:`100`,y:`123`,"text-anchor":`middle`},`Claude, Codex, …`),t(`rect`,{class:`node-accent`,x:`280`,y:`60`,width:`170`,height:`100`,rx:`10`}),t(`text`,{class:`label-title`,x:`365`,y:`95`,"text-anchor":`middle`},`imap-mcp`),t(`text`,{class:`label-muted`,x:`365`,y:`115`,"text-anchor":`middle`},`11 tools`),t(`text`,{class:`label-muted`,x:`365`,y:`133`,"text-anchor":`middle`},`asks a person`),t(`rect`,{class:`node`,x:`550`,y:`70`,width:`150`,height:`80`,rx:`10`}),t(`text`,{class:`label-title`,x:`625`,y:`103`,"text-anchor":`middle`},`IMAP`),t(`text`,{class:`label-muted`,x:`625`,y:`123`,"text-anchor":`middle`},`any IMAP mailbox`),t(`path`,{class:`edge-accent`,d:`M180,110 L272,110`,"marker-end":`url(#arch-arrow-accent)`}),t(`text`,{class:`label-mono`,x:`226`,y:`98`,"text-anchor":`middle`},`stdio`),t(`path`,{class:`edge-accent`,d:`M450,110 L542,110`,"marker-end":`url(#arch-arrow-accent)`}),t(`text`,{class:`label-mono`,x:`496`,y:`98`,"text-anchor":`middle`},`IMAP`),t(`text`,{class:`label-muted`,x:`496`,y:`130`,"text-anchor":`middle`},`TLS`),t(`path`,{class:`edge edge-dashed`,d:`M625,150 L625,196`,"marker-end":`url(#arch-arrow)`}),t(`text`,{class:`label-muted`,x:`625`,y:`216`,"text-anchor":`middle`},`This server never sends mail.`)]),t(`figcaption`,null,`The server holds no state of its own beyond short-lived approvals; what the assistant has seen lives in the mailbox, as a keyword.`)],-1),r(`<h2 id="what-it-looks-like" tabindex="-1">What it looks like <a class="header-anchor" href="#what-it-looks-like" aria-label="Permalink to “What it looks like”">​</a></h2><p><img src="/demo.gif" alt="A terminal session: listing the tools registered under the read-only default, listing an inbox, then reading a phishing message — which comes back with the injection shapes named before anything else, the body fenced line by line with a per-call nonce, and the tracking beacon defused" width="1200" height="640"></p><p>Four calls against a throwaway mailbox. The last two are the point: the message asks the assistant to forward the inbox to a stranger and carries a tracking pixel, and both arrive labelled as what they are rather than acted upon. The recording is reproducible — <code>docs/demo.tape</code> and <code>docs/demo-seed.mjs</code> build the mailbox from scratch, and nothing in it comes from a real account.</p><h2 id="running-it-elsewhere" tabindex="-1">Running it elsewhere <a class="header-anchor" href="#running-it-elsewhere" aria-label="Permalink to “Running it elsewhere”">​</a></h2><p>A client that cannot spawn a local process — ChatGPT connectors, Claude on the web, Cursor, LibreChat — cannot start imap-mcp the way Claude Code does. <a href="https://mcp-hub.ni-c.de" target="_blank" rel="noreferrer">mcp-hub</a> is the bridge: one container serves many stdio MCP servers over Streamable HTTP, with an OAuth 2.1 login behind a single password and long-lived tokens for the clients that cannot do OAuth. Its <code>/hub</code> endpoint puts every server behind six meta-tools, so one connector reaches all of them without N×tool schemas in the model&#39;s context, and it speaks both protocol revisions — a question this server asks travels through it to the person at the far end instead of ending at the gateway.</p><p>Its configuration is Claude Code&#39;s <code>mcpServers</code> format, so the entry you already have is the entry it takes: <a href="/guide/clients#through-mcp-hub">Through mcp-hub</a>.</p>`,6)]])}var c=e(o,[[`render`,s]]);export{a as __pageData,c as default};